/**
 * Per-column filtering, kept pure so the table's filter pipeline is testable without a DOM
 * and stays O(rows) per change — never per render.
 *
 * Three filter shapes cover what dashboards actually ask for (the same three TanStack's
 * column-filtering guide leads with): a substring on text, a set of allowed values on an
 * enumerated column, and a numeric range. Values arrive from the table's own inputs or from
 * a controlled `filters` prop, so the shape is a plain serialisable object — it round-trips
 * through a URL or storage unchanged.
 */

/** The kind of filter control a column offers. */
export type ColumnFilterKind = 'text' | 'select' | 'range'

/** The current value of one column's filter. An inactive filter is simply absent. */
export type ColumnFilterValue =
  | { kind: 'text'; value: string }
  | { kind: 'select'; values: string[] }
  | { kind: 'range'; min?: number; max?: number }

/** Active filters by column key. */
export type ColumnFilters = Record<string, ColumnFilterValue>

/** Whether a filter value would exclude anything at all. */
export function isFilterActive(filter: ColumnFilterValue | undefined): boolean {
  if (!filter) return false
  switch (filter.kind) {
    case 'text':
      return filter.value.trim() !== ''
    case 'select':
      return filter.values.length > 0
    case 'range':
      return filter.min !== undefined || filter.max !== undefined
  }
}

/** Number of columns with an active filter. */
export function countActiveFilters(filters: ColumnFilters): number {
  let n = 0
  for (const key in filters) if (isFilterActive(filters[key])) n++
  return n
}

/** Does one cell value pass one filter? */
export function matchesFilter(value: unknown, filter: ColumnFilterValue): boolean {
  switch (filter.kind) {
    case 'text': {
      const needle = filter.value.trim().toLowerCase()
      return (
        needle === '' ||
        String(value ?? '')
          .toLowerCase()
          .includes(needle)
      )
    }
    case 'select':
      return filter.values.length === 0 || filter.values.includes(String(value ?? ''))
    case 'range': {
      if (filter.min === undefined && filter.max === undefined) return true
      const n = typeof value === 'number' ? value : Number(value)
      if (Number.isNaN(n)) return false
      if (filter.min !== undefined && n < filter.min) return false
      if (filter.max !== undefined && n > filter.max) return false
      return true
    }
  }
}

/**
 * The rows that pass every active filter, in order. Returns `rows` itself when nothing is
 * active, so downstream memos keep their identity.
 */
export function applyColumnFilters<T>(
  rows: readonly T[],
  filters: ColumnFilters,
  valueOf: (row: T, key: string) => unknown,
): readonly T[] {
  const active: Array<[string, ColumnFilterValue]> = []
  for (const key in filters) {
    const f = filters[key]
    if (f && isFilterActive(f)) active.push([key, f])
  }
  if (active.length === 0) return rows
  const out: T[] = []
  for (const row of rows) {
    let pass = true
    for (const [key, f] of active) {
      if (!matchesFilter(valueOf(row, key), f)) {
        pass = false
        break
      }
    }
    if (pass) out.push(row)
  }
  return out
}

/** One facet: a distinct cell value and how many rows carry it. */
export interface Facet {
  value: string
  count: number
}

/**
 * Distinct values of a column with their row counts, most frequent first (ties by
 * collation). This is what a `select` filter offers as its choices — TanStack calls it
 * column faceting. One pass over the rows; the table computes it lazily, on first open.
 */
export function facetValues<T>(rows: readonly T[], valueOf: (row: T) => unknown): Facet[] {
  const counts = new Map<string, number>()
  for (const row of rows) {
    const v = String(valueOf(row) ?? '')
    counts.set(v, (counts.get(v) ?? 0) + 1)
  }
  const compare = new Intl.Collator().compare
  return [...counts.entries()]
    .map(([value, count]) => ({ value, count }))
    .sort((a, b) => b.count - a.count || compare(a.value, b.value))
}

/** The numeric extent of a column, for a `range` filter's placeholders. `undefined` if no numbers. */
export function numericExtent<T>(
  rows: readonly T[],
  valueOf: (row: T) => unknown,
): { min: number; max: number } | undefined {
  let min = Infinity
  let max = -Infinity
  for (const row of rows) {
    const v = valueOf(row)
    const n = typeof v === 'number' ? v : Number(v)
    if (Number.isNaN(n) || v === null || v === undefined || v === '') continue
    if (n < min) min = n
    if (n > max) max = n
  }
  return min <= max ? { min, max } : undefined
}

/**
 * Column layout as data: which columns show, in what order, how wide, and which stick to
 * an edge. Every transition the header menu and the resize handle perform is a pure
 * function here, so the table never reasons about layout in JSX and each rule is
 * testable on its own.
 *
 * The shape is deliberately a plain object of keys (`ColumnState`): it round-trips through
 * storage or a URL, and it survives the column definitions changing underneath it — a key
 * that no longer exists is ignored, a new column simply takes its definition position.
 */

/** Which edge a pinned column sticks to. */
export type PinSide = 'start' | 'end'

/** User-adjustable column layout. All fields optional; an absent field means "as defined". */
export interface ColumnState {
  /** Keys of hidden columns. At least one column always stays visible. */
  hidden?: string[]
  /** Display order of column keys; keys not listed follow in definition order. */
  order?: string[]
  /** Explicit widths in px, by key — what the resize handle writes. */
  widths?: Record<string, number>
  /** Pinned columns by key. Pinned-start columns render first, pinned-end last. */
  pinned?: Record<string, PinSide>
}

/** The smallest a column can be dragged to. */
export const MIN_COLUMN_WIDTH = 48

interface Keyed {
  key: string
}

/** All columns in display order — `order` first, unlisted after in definition order. */
export function orderedColumns<C extends Keyed>(columns: readonly C[], state: ColumnState): C[] {
  const order = state.order
  if (!order || order.length === 0) return [...columns]
  const byKey = new Map(columns.map((col) => [col.key, col]))
  const out: C[] = []
  for (const key of order) {
    const col = byKey.get(key)
    if (col) {
      out.push(col)
      byKey.delete(key)
    }
  }
  for (const col of columns) if (byKey.has(col.key)) out.push(col)
  return out
}

/**
 * The columns to render, in render order: pinned-start, then unpinned, then pinned-end,
 * each group in display order, hidden columns removed. Never empty — if the state hides
 * everything, the definitions win, so a stale persisted state cannot blank the table.
 */
export function displayColumns<C extends Keyed>(columns: readonly C[], state: ColumnState): C[] {
  const hidden = new Set(state.hidden ?? [])
  const pinned = state.pinned ?? {}
  const ordered = orderedColumns(columns, state).filter((col) => !hidden.has(col.key))
  if (ordered.length === 0) return [...columns]
  const start = ordered.filter((col) => pinned[col.key] === 'start')
  const middle = ordered.filter((col) => pinned[col.key] === undefined)
  const end = ordered.filter((col) => pinned[col.key] === 'end')
  return [...start, ...middle, ...end]
}

/**
 * Move `key` one step left or right among the visible columns of its own pin group. The
 * result is a complete `order` (every column key), so the move is stable under later
 * changes. Returns the same state when the column is already at the edge of its group.
 */
export function moveColumn<C extends Keyed>(
  columns: readonly C[],
  state: ColumnState,
  key: string,
  direction: -1 | 1,
): ColumnState {
  const hidden = new Set(state.hidden ?? [])
  const pinned = state.pinned ?? {}
  const all = orderedColumns(columns, state).map((col) => col.key)
  const from = all.indexOf(key)
  if (from === -1) return state
  const side = pinned[key]
  // The neighbour is the next visible column on the same side; hidden ones are skipped
  // over and other pin groups are never crossed.
  let to = from + direction
  while (to >= 0 && to < all.length) {
    const candidate = all[to] as string
    if (!hidden.has(candidate) && pinned[candidate] === side) break
    if (pinned[candidate] !== side) return state
    to += direction
  }
  if (to < 0 || to >= all.length) return state
  const next = [...all]
  next.splice(from, 1)
  next.splice(to, 0, key)
  return { ...state, order: next }
}

/** Pin `key` to a side, or unpin it with `null`. */
export function pinColumn(state: ColumnState, key: string, side: PinSide | null): ColumnState {
  const pinned = { ...state.pinned }
  if (side === null) delete pinned[key]
  else pinned[key] = side
  return { ...state, pinned }
}

/** Set an explicit width for `key`, or clear it with `undefined` to return to auto. */
export function resizeColumn(
  state: ColumnState,
  key: string,
  width: number | undefined,
): ColumnState {
  const widths = { ...state.widths }
  if (width === undefined) delete widths[key]
  else widths[key] = Math.max(MIN_COLUMN_WIDTH, Math.round(width))
  return { ...state, widths }
}

/** Hide or show `key`. Hiding the last visible column is refused. */
export function toggleColumnHidden<C extends Keyed>(
  columns: readonly C[],
  state: ColumnState,
  key: string,
): ColumnState {
  const hidden = state.hidden ?? []
  if (hidden.includes(key)) return { ...state, hidden: hidden.filter((k) => k !== key) }
  const visible = columns.filter((col) => !hidden.includes(col.key))
  if (visible.length <= 1) return state
  return { ...state, hidden: [...hidden, key] }
}

/**
 * Sticky insets for a row of cells, given each cell's measured width and which side (if
 * any) it is pinned to. A pinned-start cell sits after every pinned-start cell before it;
 * a pinned-end cell before every pinned-end cell after it. Unpinned cells get `undefined`.
 */
export function stickyOffsets(
  widths: readonly number[],
  sides: readonly (PinSide | undefined)[],
): (number | undefined)[] {
  const out: (number | undefined)[] = Array.from({ length: widths.length })
  let acc = 0
  for (let i = 0; i < widths.length; i++) {
    if (sides[i] === 'start') {
      out[i] = acc
      acc += widths[i] as number
    }
  }
  acc = 0
  for (let i = widths.length - 1; i >= 0; i--) {
    if (sides[i] === 'end') {
      out[i] = acc
      acc += widths[i] as number
    }
  }
  return out
}

/**
 * The keyboard model of the APG data-grid pattern, as arithmetic on a cell coordinate.
 *
 * A grid has ONE tab stop; inside it the arrow keys move a focus cell, Home/End jump within
 * the row, Ctrl+Home/End to the corners, PageUp/PageDown by a page of rows. Kept pure so
 * the whole key map is testable without a DOM and so virtualization (the focused row may
 * not be rendered yet) is the table's problem, not this file's.
 */

/** A focus position: `row` is -1 for the header row, otherwise a 0-based body row. */
export interface GridCell {
  row: number
  col: number
}

export interface GridBounds {
  /** Body rows in the collection (not just the rendered window). */
  rowCount: number
  /** Cells per row, control columns included. */
  colCount: number
  /** Rows one PageUp/PageDown moves by. */
  pageRows: number
}

/**
 * The next focus cell for a key, or `undefined` when the key is not a grid-navigation key.
 * Returns the same coordinate at an edge, so the caller can still `preventDefault` without
 * moving.
 */
export function moveGridFocus(
  cell: GridCell,
  key: string,
  bounds: GridBounds,
  ctrl = false,
): GridCell | undefined {
  const lastRow = bounds.rowCount - 1
  const lastCol = bounds.colCount - 1
  const clampRow = (row: number) => Math.max(-1, Math.min(lastRow, row))
  const clampCol = (col: number) => Math.max(0, Math.min(lastCol, col))
  switch (key) {
    case 'ArrowDown':
      return { row: clampRow(cell.row + 1), col: cell.col }
    case 'ArrowUp':
      return { row: clampRow(cell.row - 1), col: cell.col }
    case 'ArrowRight':
      return { row: cell.row, col: clampCol(cell.col + 1) }
    case 'ArrowLeft':
      return { row: cell.row, col: clampCol(cell.col - 1) }
    case 'Home':
      return ctrl ? { row: clampRow(0), col: 0 } : { row: cell.row, col: 0 }
    case 'End':
      return ctrl ? { row: lastRow, col: lastCol } : { row: cell.row, col: lastCol }
    case 'PageDown':
      return { row: clampRow(cell.row + bounds.pageRows), col: cell.col }
    case 'PageUp':
      return { row: clampRow(cell.row - bounds.pageRows), col: cell.col }
    default:
      return undefined
  }
}

/**
 * Row grouping, aggregation and column-group spans as data. The table's body is a flat
 * list either way — grouping just interleaves group rows with the leaf rows they own, so
 * paging, the virtual window and the grid keyboard model need no notion of a tree.
 */

/** Built-in aggregations for `Column.aggregate`. */
export type AggregateKind = 'sum' | 'avg' | 'min' | 'max' | 'count'

/** A band of columns under one header (`columnGroups`). */
export interface ColumnGroup {
  header: string
  /** Column keys in the band. Non-adjacent keys render as separate spans. */
  columns: string[]
}

export interface GroupInfo {
  /** Stable identity: the path of `column=value` pairs down to this group. */
  key: string
  /** The column this level groups on. */
  column: string
  value: unknown
  depth: number
  /** Leaf rows under the group, at every depth. */
  count: number
  collapsed: boolean
}

/** A group row in the flattened list; `leaves` are the rows it owns. */
export interface GroupItem<T> {
  id: string
  group: GroupInfo
  leaves: readonly T[]
}

// A unit separator: no cell value contains one, so a path cannot be forged by a value.
const PATH_SEPARATOR = '\u001f'

/**
 * Interleave group rows with `items`, one level per key, keeping the items' order inside
 * each group (so a sorted input stays sorted) and the groups in order of first
 * appearance. Leaves under a collapsed group are omitted; the group row stays.
 */
export function groupItems<T extends { id: string }>(
  items: readonly T[],
  keys: readonly string[],
  valueOf: (item: T, key: string) => unknown,
  collapsed: ReadonlySet<string>,
): (T | GroupItem<T>)[] {
  const out: (T | GroupItem<T>)[] = []
  const walk = (rows: readonly T[], depth: number, prefix: string) => {
    const column = keys[depth]
    if (column === undefined) {
      for (const row of rows) out.push(row)
      return
    }
    const buckets = new Map<string, { value: unknown; rows: T[] }>()
    for (const row of rows) {
      const value = valueOf(row, column)
      const label = String(value ?? '')
      const bucket = buckets.get(label)
      if (bucket) bucket.rows.push(row)
      else buckets.set(label, { value, rows: [row] })
    }
    for (const [label, bucket] of buckets) {
      const key = `${prefix}${column}=${label}`
      const isCollapsed = collapsed.has(key)
      out.push({
        id: `group${PATH_SEPARATOR}${key}`,
        group: {
          key,
          column,
          value: bucket.value,
          depth,
          count: bucket.rows.length,
          collapsed: isCollapsed,
        },
        leaves: bucket.rows,
      })
      if (!isCollapsed) walk(bucket.rows, depth + 1, `${key}${PATH_SEPARATOR}`)
    }
  }
  walk(items, 0, '')
  return out
}

/**
 * One number for a column over a set of rows. Non-numeric, blank and null values are
 * skipped (a `count` counts rows, not numbers); `undefined` when nothing was numeric.
 */
export function aggregate(values: readonly unknown[], kind: AggregateKind): number | undefined {
  if (kind === 'count') return values.length
  let sum = 0
  let n = 0
  let min = Infinity
  let max = -Infinity
  for (const value of values) {
    if (value === null || value === undefined || value === '') continue
    const x = typeof value === 'number' ? value : Number(value)
    if (Number.isNaN(x)) continue
    n++
    sum += x
    if (x < min) min = x
    if (x > max) max = x
  }
  if (n === 0) return undefined
  switch (kind) {
    case 'sum':
      return sum
    case 'avg':
      return sum / n
    case 'min':
      return min
    default:
      return max
  }
}

/**
 * The header cells of the column-group row, for the visible columns in render order: a
 * run of adjacent columns in the same group becomes one spanning cell; columns in no
 * group (or split from their group by reordering) get an unlabelled span.
 */
export function headerSpans(
  columnKeys: readonly string[],
  groups: readonly ColumnGroup[],
): { header: string | undefined; span: number }[] {
  const groupOf = new Map<string, string>()
  for (const group of groups) for (const key of group.columns) groupOf.set(key, group.header)
  const out: { header: string | undefined; span: number }[] = []
  for (const key of columnKeys) {
    const header = groupOf.get(key)
    const last = out[out.length - 1]
    if (last && last.header === header) last.span++
    else out.push({ header, span: 1 })
  }
  return out
}

/**
 * Substring search over rows that stays cheap while the user types.
 *
 * The naive filter — `String(cell).toLowerCase().includes(q)` per column per row on every
 * keystroke — is what a million-row table paid: ~500–850 ms of main-thread time per key
 * (measured), so the search box lagged a word behind the user. Two things fix it:
 *
 * 1. **One haystack per row.** `haystackOf` is expected to be cached by the caller (the
 *    table keys a `Map` on the row entry), so a key costs one `includes` per row, not one
 *    `String`/`toLowerCase` per cell.
 * 2. **Incremental narrowing.** A query that extends the previous one (`per` → `pers`) can
 *    only match a subset of the previous result, so it is filtered from that result rather
 *    than from every row. Typing gets cheaper with every character; only a shorter or
 *    different query — or a different base `rows` array — starts over.
 *
 * Order is preserved, which is what lets the table sort **once** and filter the sorted rows
 * per keystroke instead of re-sorting the filtered rows.
 */
export interface RowSearch<T> {
  /** The rows of `rows` whose haystack contains `query` (lower-cased, trimmed by the caller), in order. */
  filter(rows: readonly T[], query: string): readonly T[]
  /**
   * Build the haystacks of `rows[from, from + count)` ahead of any query, so the first
   * keystroke does not pay for the whole index (~1.5 s at a million rows). Returns the next
   * index to prime; the caller spreads calls over idle time.
   */
  prime(rows: readonly T[], from: number, count: number): number
}

/** Build a {@link RowSearch}; `haystackOf` yields the lower-cased searchable text of one row. */
export function createRowSearch<T>(haystackOf: (row: T) => string): RowSearch<T> {
  let lastRows: readonly T[] | undefined
  let lastQuery = ''
  let lastResult: readonly T[] = []

  return {
    filter(rows, query) {
      if (query === '') {
        lastRows = rows
        lastQuery = ''
        lastResult = rows
        return rows
      }
      const sameBase = rows === lastRows
      if (sameBase && query === lastQuery) return lastResult
      const narrowing = sameBase && lastQuery !== '' && query.startsWith(lastQuery)
      const candidates = narrowing ? lastResult : rows
      const out: T[] = []
      for (const row of candidates) if (haystackOf(row).includes(query)) out.push(row)
      lastRows = rows
      lastQuery = query
      lastResult = out
      return out
    },
    prime(rows, from, count) {
      const to = Math.min(rows.length, from + count)
      for (let i = from; i < to; i++) haystackOf(rows[i] as T)
      return to
    },
  }
}

/**
 * Stable client-side sort of rows by one column.
 *
 * The comparator-per-pair approach — `String(a).localeCompare(String(b))` inside
 * `Array.prototype.sort` — took **~4 s** to sort a million names (measured in Chromium):
 * `localeCompare` resolves a collator on every call, and the string conversion ran ~20
 * million times. What replaces it:
 *
 * - **Keys are extracted once per row**, not once per comparison.
 * - **Numbers compare by subtraction**; no collator is touched when every key is a number.
 * - **Strings are ranked, then the ranks are sorted.** The distinct values are collated once
 *   with a single `Intl.Collator` and given integer ranks, and the rows are then sorted by
 *   rank — a numeric sort. A status or city column with a few hundred distinct values sorts
 *   a million rows in the time it takes to sort a few hundred strings; a column of unique
 *   strings still pays one collation sort of its values, which is the floor.
 *
 * Ties break on original position, so the sort is stable regardless of engine.
 */
export function sortRows<T>(
  rows: readonly T[],
  keyOf: (row: T) => unknown,
  direction: 'asc' | 'desc',
): T[] {
  return sortRowsBy(rows, [{ keyOf, direction }])
}

/** One level of a multi-column sort. */
export interface SortLevel<T> {
  keyOf: (row: T) => unknown
  direction: 'asc' | 'desc'
}

/**
 * Sort by several columns: the first level orders the rows, each later level only breaks
 * ties left by the ones before it. Every level's keys are ranked once up front, so the
 * comparator is a fixed number of subtractions per pair regardless of how many levels.
 */
export function sortRowsBy<T>(rows: readonly T[], levels: readonly SortLevel<T>[]): T[] {
  const n = rows.length
  if (n < 2 || levels.length === 0) return [...rows]
  // A plain array: a typed array sorts ~2x slower under a JS comparator (measured).
  const order = Array.from({ length: n }, (_, i) => i)
  const collect = (): T[] => order.map((i) => rows[i] as T)
  const compare = new Intl.Collator().compare

  const rankSets: Float64Array[] = []
  const signs: number[] = []
  for (const level of levels) {
    const keys: unknown[] = Array.from({ length: n })
    let allNumbers = true
    for (let i = 0; i < n; i++) {
      const k = level.keyOf(rows[i] as T)
      keys[i] = k
      if (typeof k !== 'number') allNumbers = false
    }
    const sign = level.direction === 'desc' ? -1 : 1
    const ranks = new Float64Array(n)
    if (allNumbers) {
      for (let i = 0; i < n; i++) ranks[i] = keys[i] as number
    } else {
      const strings: string[] = Array.from({ length: n })
      for (let i = 0; i < n; i++) strings[i] = String(keys[i] ?? '')
      if (levels.length === 1 && mostlyDistinct(strings)) {
        // Ranking would only add a map over a million entries before the same collation
        // sort; compare the strings directly.
        order.sort((a, b) => {
          const r = compare(strings[a] as string, strings[b] as string)
          return r !== 0 ? sign * r : a - b
        })
        return collect()
      }
      // Rank the distinct strings by collation; a row's sort key is its string's rank.
      const rankOf = new Map<string, number>()
      for (let i = 0; i < n; i++) rankOf.set(strings[i] as string, 0)
      const distinct = [...rankOf.keys()].sort(compare)
      for (let r = 0; r < distinct.length; r++) rankOf.set(distinct[r] as string, r)
      for (let i = 0; i < n; i++) ranks[i] = rankOf.get(strings[i] as string) as number
    }
    rankSets.push(ranks)
    signs.push(sign)
  }

  const depth = rankSets.length
  order.sort((a, b) => {
    for (let d = 0; d < depth; d++) {
      const ranks = rankSets[d] as Float64Array
      const r = (ranks[a] as number) - (ranks[b] as number)
      if (r !== 0) return (signs[d] as number) * r
    }
    return a - b
  })
  return collect()
}

/** Sampled cardinality: are the first couple of thousand values almost all different? */
function mostlyDistinct(strings: readonly string[]): boolean {
  const sample = Math.min(strings.length, 2048)
  const seen = new Set<string>()
  for (let i = 0; i < sample; i++) seen.add(strings[i] as string)
  return seen.size > sample * 0.9
}

/**
 * RFC 4180 CSV for the table's export button: CRLF records, a field quoted whenever it
 * holds a comma, a quote, a CR or an LF, quotes doubled. Values are the raw cell values
 * (not the rendered cells), stringified the way the default cell is: `null`/`undefined`
 * become an empty field.
 */

interface CsvColumn {
  key: string
  header: string
}

export function csvField(value: unknown): string {
  const text = value === null || value === undefined ? '' : String(value)
  return /[",\r\n]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text
}

/** The CSV document: one header record from `columns`, then one record per row. */
export function toCsv<Row>(
  rows: readonly Row[],
  columns: readonly CsvColumn[],
  valueOf: (row: Row, key: string) => unknown,
): string {
  const lines = [columns.map((col) => csvField(col.header)).join(',')]
  for (const row of rows) {
    lines.push(columns.map((col) => csvField(valueOf(row, col.key))).join(','))
  }
  return lines.join('\r\n') + '\r\n'
}

/**
 * Hand a CSV to the browser as a download. Prefixed with a byte-order mark so spreadsheet
 * apps read non-ASCII text as UTF-8 rather than guessing a legacy code page.
 */
export function downloadCsv(csv: string, filename: string): void {
  const blob = new Blob(['\uFEFF', csv], { type: 'text/csv;charset=utf-8' })
  const url = URL.createObjectURL(blob)
  const anchor = document.createElement('a')
  anchor.href = url
  anchor.download = filename.endsWith('.csv') ? filename : `${filename}.csv`
  anchor.click()
  URL.revokeObjectURL(url)
}

/**
 * The arithmetic behind the virtualized row window, kept pure so the two things that
 * decide whether a million-row table works — *which* rows to render, and *where* to put
 * them — are unit-testable without a DOM.
 *
 * Positions are arithmetic on a fixed row height (the density presets size every row to
 * `--_row-height`), so scrolling never measures. The one twist is the **canvas cap**:
 * browsers clamp an element's height — Chromium at 33,554,432 px, Firefox at 17,895,697 px
 * — and a million 49 px rows is 49,000,000 px. Sized honestly, the scroller silently stops
 * at the cap and the last ~160k rows can never be scrolled to (measured: 1,000,000 rows,
 * bottom of the scrollbar, last rendered row 838,871). So the canvas is capped and, above
 * the cap, the scroll position is mapped onto the row space by ratio, exactly the way the
 * big grids do it. Below the cap the ratio is 1 and the layout is byte-identical to the
 * naive spacer layout.
 */

/**
 * Tallest canvas the scroller is allowed to be. Under every engine's clamp with room to
 * spare, and still ~1.3 s of continuous wheel-scrolling from top to bottom at a typical
 * 240 px per tick, so the scrollbar stays a usable control.
 */
export const MAX_CANVAS_PX = 12_000_000

export interface WindowInput {
  /** The scroller's current `scrollTop`, in canvas pixels. */
  scrollTop: number
  /** The scroller's `clientHeight`. */
  viewportHeight: number
  /** Height of one row, in px. Must be > 0. */
  rowHeight: number
  /** Total rows in the collection being windowed. */
  count: number
  /** Rows rendered beyond each edge of the viewport. */
  overscan: number
  /** Canvas cap; exposed for tests. */
  maxCanvas?: number
}

export interface RowWindow {
  /** First rendered row (inclusive). */
  start: number
  /** Last rendered row (exclusive). */
  end: number
  /** Height of the spacer above the first rendered row, in canvas px. */
  topPad: number
  /** Height of the spacer below the last rendered row, in canvas px. */
  bottomPad: number
  /** Total canvas height — what the scroller's `scrollHeight` should come to. */
  canvasHeight: number
  /** Canvas px per row px. 1 below the cap. */
  scale: number
}

/** The rows to render for a scroll position, and the spacers that place them there. */
export function computeWindow(input: WindowInput): RowWindow {
  const { viewportHeight, rowHeight, count, overscan } = input
  const maxCanvas = input.maxCanvas ?? MAX_CANVAS_PX
  const contentHeight = count * rowHeight
  const canvasHeight = Math.min(contentHeight, maxCanvas)
  if (count === 0) return { start: 0, end: 0, topPad: 0, bottomPad: 0, canvasHeight: 0, scale: 1 }

  // How far the user has scrolled, as a fraction of the scrollable range, is the only
  // quantity that survives the cap: the same fraction of the row space is what they mean.
  const scrollable = Math.max(0, canvasHeight - viewportHeight)
  const scrollTop = Math.max(0, Math.min(input.scrollTop, scrollable))
  const scale = scrollable > 0 ? Math.max(0, contentHeight - viewportHeight) / scrollable : 1
  const contentTop = scrollTop * scale

  const firstVisible = Math.min(count - 1, Math.floor(contentTop / rowHeight))
  const visibleRows = Math.ceil(viewportHeight / rowHeight) + 1
  const start = Math.max(0, firstVisible - overscan)
  const end = Math.min(count, firstVisible + visibleRows + overscan)

  // Place the window so that `firstVisible` sits exactly where it would in an uncapped
  // layout relative to the viewport: at the scroll position, minus however far into the
  // row the viewport has already scrolled, minus the overscan rows above it.
  const withinRow = contentTop - firstVisible * rowHeight
  const topPad = Math.max(0, scrollTop - withinRow - (firstVisible - start) * rowHeight)
  const bottomPad = Math.max(0, canvasHeight - topPad - (end - start) * rowHeight)
  return { start, end, topPad, bottomPad, canvasHeight, scale }
}

/**
 * The `scrollTop` that centres `row` in the viewport — the inverse of {@link computeWindow}'s
 * mapping, so a keyboard user landing on a row outside the rendered window is scrolled to
 * it under the same canvas cap. Clamped to the scrollable range.
 */
export function scrollTopForRow(row: number, input: Omit<WindowInput, 'scrollTop'>): number {
  const { viewportHeight, rowHeight, count } = input
  const maxCanvas = input.maxCanvas ?? MAX_CANVAS_PX
  const contentHeight = count * rowHeight
  const canvasHeight = Math.min(contentHeight, maxCanvas)
  const scrollable = Math.max(0, canvasHeight - viewportHeight)
  if (scrollable === 0) return 0
  const scale = Math.max(0, contentHeight - viewportHeight) / scrollable
  const contentTop = Math.max(0, row * rowHeight - (viewportHeight - rowHeight) / 2)
  return Math.max(0, Math.min(scrollable, Math.round(contentTop / scale)))
}

@layer cascivo.component {
  .root {
    --_row-height: 3rem;
    display: flex;
    flex-direction: column;
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-sm);
    color: var(--cascivo-color-text);
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-surface);
    background-color: var(--cascivo-color-surface);
    overflow: hidden;
  }

  .root[data-density='compact'] {
    --_row-height: 2.25rem;
  }
  .root[data-density='normal'] {
    --_row-height: 3rem;
  }
  .root[data-density='relaxed'] {
    --_row-height: 3.75rem;
  }

  /* Toolbar */
  .toolbar {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: var(--cascivo-space-4);
    padding: var(--cascivo-space-3) var(--cascivo-space-4);
    border-block-end: 1px solid var(--cascivo-color-border);
  }

  .heading {
    display: flex;
    flex-direction: column;
    gap: var(--cascivo-space-1);
  }

  .title {
    font-size: var(--cascivo-text-base);
    font-weight: var(--cascivo-font-semibold);
    color: var(--cascivo-color-text);
  }

  .description {
    font-size: var(--cascivo-text-sm);
    color: var(--cascivo-color-text-subtle);
  }

  .search {
    appearance: none;
    height: 2rem;
    min-inline-size: 14rem;
    padding-inline: var(--cascivo-space-3);
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-sm);
    color: var(--cascivo-color-text);
    background-color: var(--cascivo-color-surface);
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-field);
    outline: none;
    transition:
      border-color var(--cascivo-duration-150) var(--cascivo-ease-out),
      box-shadow var(--cascivo-duration-150) var(--cascivo-ease-out);

    &:hover:not(:focus) {
      border-color: var(--cascivo-color-border-strong);
    }

    &:focus-visible {
      border-color: var(--cascivo-color-accent);
      box-shadow: 0 0 0 3px color-mix(in srgb, var(--cascivo-color-accent) 20%, transparent);
    }
  }

  /* Search, filter reset, caller toolbar controls and the Columns menu, as one cluster. */
  .toolbarActions {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: flex-end;
    gap: var(--cascivo-space-2);
  }

  /* Column-visibility and facet menus: a checklist in a popover. */
  .menu {
    display: flex;
    flex-direction: column;
    gap: var(--cascivo-space-1);
    min-inline-size: 12rem;
    max-block-size: 20rem;
    overflow: auto;
    padding: var(--cascivo-space-2);
  }

  /* Per-column filter row under the header: same band as the header, plain text. */
  .filterRow th {
    padding-block: var(--cascivo-space-1);
    font-weight: var(--cascivo-font-medium);
    text-transform: none;
    letter-spacing: normal;
  }

  .filterInput {
    appearance: none;
    inline-size: 100%;
    min-inline-size: 4rem;
    block-size: 1.75rem;
    padding-inline: var(--cascivo-space-2);
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-sm);
    color: var(--cascivo-color-text);
    background-color: var(--cascivo-color-surface);
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-field);
    outline: none;

    &:focus-visible {
      border-color: var(--cascivo-color-accent);
      box-shadow: 0 0 0 3px color-mix(in srgb, var(--cascivo-color-accent) 20%, transparent);
    }
  }

  .rangeInputs {
    display: flex;
    gap: var(--cascivo-space-1);

    .filterInput {
      min-inline-size: 3.5rem;
    }
  }

  /* Batch bar */
  .batchBar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--cascivo-space-4);
    padding: var(--cascivo-space-2) var(--cascivo-space-4);
    background-color: var(--cascivo-color-bg-subtle);
    border-block-end: 1px solid var(--cascivo-color-border);
  }

  .batchCount {
    font-size: var(--cascivo-text-sm);
    font-weight: var(--cascivo-font-medium);
    color: var(--cascivo-color-text);
  }

  .batchActions {
    display: flex;
    gap: var(--cascivo-space-2);
  }

  /* Table scroller */
  .scroller {
    overflow: auto;
    max-block-size: var(--cascivo-data-table-max-height, none);
    /* Reserve the gutter so a horizontally-scrollable table SAYS so. With an overlay
       scrollbar (the default on macOS and Android) columns past the fold simply vanish and
       it reads as "the table dropped my columns" — one adopter measured clientWidth 1052
       against scrollWidth 1360 before working out the rows were scrollable at all. */
    scrollbar-gutter: stable;

    /* Scrolling shadows: a soft edge appears only on the side there is more table to reach.
       `scrollbar-gutter` above says "this scrolls"; this says WHICH WAY and that content is
       cut off right now — the missing affordance behind a reported "the Created column was
       cut off at the right edge with no visible scrollbar" (2026-08-22 report item 17).

       Pure CSS, no JS and no scroll listener: the cover gradients scroll WITH the content
       (`local`) and hide the shadows when the table is flush against an edge, while the
       shadows are fixed to the box (`scroll`). A table that fits shows neither. */
    background-image:
      linear-gradient(to right, var(--cascivo-color-surface) 30%, transparent),
      linear-gradient(to left, var(--cascivo-color-surface) 30%, transparent),
      radial-gradient(farthest-side at 0 50%, var(--cascivo-color-border), transparent),
      radial-gradient(farthest-side at 100% 50%, var(--cascivo-color-border), transparent);
    background-position:
      0 0,
      100% 0,
      0 0,
      100% 0;
    background-repeat: no-repeat;
    background-size:
      2.5rem 100%,
      2.5rem 100%,
      0.875rem 100%,
      0.875rem 100%;
    background-attachment: local, local, scroll, scroll;
  }

  .scrollerVirtualized {
    overflow: auto;
    block-size: var(--cascivo-data-table-height, 400px);
    max-block-size: none;
  }

  .table {
    inline-size: 100%;
    border-collapse: collapse;
    table-layout: auto;
  }

  /* A fixed layout keeps column widths constant as the page changes, but it hands
     unsized columns only the leftover space with no content floor. With six of seven
     columns sized, the seventh collapsed to ~50px and wrapped one character per line.
     So it applies only when EVERY column declares a width — the one case where the
     stability guarantee costs nothing. Otherwise widths are preferred sizes under the
     auto algorithm, which still respects each column's content minimum. */
  .root[data-paginated='true'][data-fixed-layout='true'] .table {
    table-layout: fixed;
  }

  .table thead th {
    padding-block: var(--cascivo-space-2);
    padding-inline: var(--cascivo-data-table-cell-gap, var(--cascivo-space-4));
    text-align: start;
    font-weight: var(--cascivo-font-semibold);
    font-size: var(--cascivo-text-xs);
    text-transform: uppercase;
    letter-spacing: var(--cascivo-tracking-wide);
    color: var(--cascivo-color-text-subtle);
    background-color: var(--cascivo-color-bg-subtle);
    border-block-end: 1px solid var(--cascivo-color-border);
    white-space: nowrap;
  }

  .table thead th[data-align='end'] {
    text-align: end;
  }

  .table td {
    padding-block: 0;
    padding-inline: var(--cascivo-data-table-cell-gap, var(--cascivo-space-4));
    block-size: var(--_row-height);
    vertical-align: middle;
    border-block-end: 1px solid var(--cascivo-color-border);
    color: var(--cascivo-color-text);
  }

  /* Long unbroken tokens (commit hashes, branch names) wrap inside the cell instead of
     spilling past the padding into the adjacent column. Scoped to columns that declared a
     `width` — that is the identifier-shaped case this exists for. Applying it to a
     free-form column made a squeezed column wrap one character per line instead of
     pushing back on the layout. */
  /* A sized column must not be squeezed below its own content.
     `width` is a *preferred* size, but under `table-layout: fixed` — which kicks in once
     every column is sized — the browser will happily shrink one below its text, and
     `overflow-wrap: anywhere` then broke words mid-character ("Buildin" / "g"). The docs
     promised unsized columns never collapse below their content; sized ones now get the
     same floor.

     `break-word` rather than `anywhere` is load-bearing: `anywhere` participates in
     min-content sizing (making the floor one character wide, i.e. no floor at all), while
     `break-word` leaves min-content at the longest word and still wraps unbreakable
     strings. Pass `minWidth` to raise the floor above the content. */
  .table td[data-sized],
  .table th[data-sized] {
    overflow-wrap: break-word;
    min-inline-size: min-content;
  }

  .table td[data-align='end'] {
    text-align: end;
  }

  /* Spacer that pads partial pages to a constant height — no divider line. */
  .table tbody tr[data-filler-row] td {
    border-block-end: none;
  }

  /* Sticky header */
  .root[data-sticky-header='true'] .table thead th {
    position: sticky;
    inset-block-start: 0;
    z-index: var(--cascivo-z-raised, 10);
    background-color: var(--cascivo-color-surface);
  }

  /* With a column-group row above it, the header row sticks under that; `--_group-h` is
     measured (0 without groups). */
  .root[data-sticky-header='true'] .table thead tr:not([data-group-header]) th {
    inset-block-start: var(--_group-h, 0px);
  }

  /* The filter row sticks just under the header row; `--_head-h` is measured. */
  .root[data-sticky-header='true'] .table thead .filterRow th {
    inset-block-start: calc(var(--_group-h, 0px) + var(--_head-h, 2.5rem));
  }

  /* Pinned top rows stack under the whole head; each row's `--_pin-index` is its slot. */
  .root[data-sticky-header='true'] .table tbody tr[data-pinned-row='top'] td {
    position: sticky;
    inset-block-start: calc(var(--_thead-h, 0px) + var(--_pin-index, 0) * var(--_row-height));
    z-index: var(--cascivo-z-raised, 10);
  }

  .table tbody tr[data-pinned-row] td {
    background-color: var(--cascivo-color-bg-subtle);
    font-weight: var(--cascivo-font-medium);
  }

  /* The totals row sticks to the bottom of the scroller as one block. */
  .table .totals {
    position: sticky;
    inset-block-end: 0;
    z-index: var(--cascivo-z-raised, 10);
  }

  /* `.table td` already sizes and pads these cells. */
  .table .totals td {
    background-color: var(--cascivo-color-bg-subtle);
    border-block-start: 2px solid var(--cascivo-color-border);
    font-weight: var(--cascivo-font-semibold);
  }

  .table .totals td[data-align='end'] {
    text-align: end;
  }

  /* Column-group header: a band label centred over its columns. */
  .table thead th.groupHeader {
    text-align: center;
    border-block-end: none;
    border-inline-end: 1px solid var(--cascivo-color-border);
    color: var(--cascivo-color-text);
  }

  .table thead th.groupHeader:empty {
    border-inline-end: none;
  }

  /* Group rows: a toggle with the group's value and count, aggregates in the other cells. */
  .table .groupRow td {
    background-color: var(--cascivo-color-bg-subtle);
    font-weight: var(--cascivo-font-semibold);
  }

  .table .groupRow td[data-align='end'] {
    text-align: end;
  }

  .groupToggle {
    display: inline-flex;
    align-items: center;
    gap: var(--cascivo-space-2);
    padding: 0;
    border: none;
    background: none;
    font: inherit;
    color: inherit;
    cursor: pointer;

    &:focus-visible {
      outline: 2px solid var(--cascivo-color-accent);
      outline-offset: 2px;
      border-radius: var(--cascivo-radius-sm);
    }
  }

  .groupToggle[data-state='open'] .chevron {
    transform: rotate(-135deg);
  }

  .groupCount {
    font-weight: var(--cascivo-font-normal);
    color: var(--cascivo-color-text-muted);
  }

  /*
    A stuck header needs to say it is stuck. Until `scroll-state` there was no way to know:
    the header looks identical whether it is sitting in normal flow at the top of the table
    or floating over rows that have scrolled under it, so the first row reads as a header
    row. The horizontal affordance right below (`.scroller`'s local/scroll gradients) solved
    the same problem on the other axis and is the model for this one — CSS only, no listener.

    `container-type: scroll-state` on the scroller lets its descendants ask; `thead th` is a
    descendant, so this needs no wrapper and no DOM change. Progressive enhancement
    (Chrome 133+): elsewhere the header stays flat, exactly as it is today.
  */
  @supports (container-type: scroll-state) {
    /* `stuck` is asked OF the sticky element, so the header cell is the container — and a
       container cannot style itself, so the rule below paints the cell's own `::after`
       (verified in Chromium 141 against a real sticky `<th>`). */
    .root[data-sticky-header='true'] .table thead th {
      container-type: scroll-state;
    }

    @container scroll-state(stuck: top) {
      .root[data-sticky-header='true'] .table thead th::after {
        content: '';
        position: absolute;
        inset-inline: 0;
        inset-block-end: 0;
        block-size: 0.375rem;
        translate: 0 100%;
        pointer-events: none;
        background: linear-gradient(
          to bottom,
          color-mix(in srgb, var(--cascivo-color-text) 12%, transparent),
          transparent
        );
      }
    }
  }

  /* Zebra striping — `of .row` keeps expansion rows out of the count.

     NOT `--cascivo-color-bg-subtle`: every theme aliases that straight to
     `--cascivo-color-surface` (`themes/src/*.css`), so striping a table that sits on a
     surface — a table in a Card, which is the normal composition — painted the row the
     exact colour it already was. Measured ΔL of 0.0000 in all three themes; the prop was
     wired and did nothing, which is what the adopter reported as "no visible effect"
     (2026-08-08 report A).

     A translucent foreground overlay adapts instead of assuming: it darkens on light themes
     and lightens on dark ones, and it works on ANY background the table is placed on rather
     than only on the page background. */
  .root[data-zebra='true'] .table tbody tr:nth-child(even of .row) {
    background-color: var(
      --cascivo-table-zebra-bg,
      color-mix(in oklab, var(--cascivo-color-text) 5%, transparent)
    );
  }

  /* Header cells hold a label, optionally a column menu and a resize handle. */
  .headerCell {
    position: relative;
  }

  .headerInner {
    display: inline-flex;
    align-items: center;
    gap: var(--cascivo-space-1);
    max-inline-size: 100%;
  }

  /* Drag handle on the trailing edge of a resizable header; a focusable separator so the
     keyboard gets the same control (arrows nudge, Home resets). */
  .resizeHandle {
    position: absolute;
    inset-block: 0;
    inset-inline-end: 0;
    inline-size: 0.5rem;
    cursor: col-resize;
    touch-action: none;
    user-select: none;
    outline: none;

    &::after {
      content: '';
      position: absolute;
      inset-block: 25%;
      inset-inline-end: 0.125rem;
      inline-size: 2px;
      border-radius: 1px;
      background-color: transparent;
      transition: background-color var(--cascivo-duration-150) var(--cascivo-ease-out);
    }

    &:hover::after,
    &:focus-visible::after,
    &[data-state='resizing']::after {
      background-color: var(--cascivo-color-accent);
    }
  }

  /* A user-resized table keeps its column widths exactly: fixed layout, no redistribution
     back to content weight. */
  .root[data-resized='true'] .table {
    table-layout: fixed;
  }

  /* Pinned columns stick to an edge; insets are measured and set inline. The scroller's
     shadows already mark cut-off content, so the pinned edge only needs a hairline. */
  .table th[data-pinned],
  .table td[data-pinned] {
    position: sticky;
    z-index: 1;
    background-color: var(--cascivo-color-surface);
  }

  .table thead th[data-pinned] {
    z-index: calc(var(--cascivo-z-raised, 10) + 1);
  }

  .table th[data-pinned='start'][data-pinned-edge],
  .table td[data-pinned='start'][data-pinned-edge] {
    box-shadow: inset -1px 0 0 var(--cascivo-color-border);
  }

  .table th[data-pinned='end'][data-pinned-edge],
  .table td[data-pinned='end'][data-pinned-edge] {
    box-shadow: inset 1px 0 0 var(--cascivo-color-border);
  }

  /* Control columns (expand button / checkbox) */
  .controlCol {
    inline-size: 3rem;
  }

  .controlCell {
    text-align: center;
    padding-inline: var(--cascivo-space-2);
  }

  /* Sort button */
  .sortButton {
    display: inline-flex;
    align-items: center;
    gap: var(--cascivo-space-1);
    background: none;
    border: none;
    padding: 0;
    font-family: inherit;
    font-size: inherit;
    font-weight: inherit;
    text-transform: inherit;
    letter-spacing: inherit;
    color: inherit;
    cursor: pointer;
    outline: none;

    &:focus-visible {
      text-decoration: underline;
    }

    &::after {
      content: '↕';
      font-size: 0.75em;
      opacity: 0.4;
    }

    &[data-state='ascending']::after {
      content: '↑';
      opacity: 0.9;
    }

    &[data-state='descending']::after {
      content: '↓';
      opacity: 0.9;
    }
  }

  /* Multi-sort level badge (1, 2, 3…) next to a sorted header. */
  .sortIndex {
    font-size: 0.65em;
    line-height: 1;
    margin-inline-start: 0.125rem;
    color: var(--cascivo-color-text-muted);
  }

  /* Row */
  .row {
    content-visibility: auto;
    contain-intrinsic-size: auto var(--_row-height, 3rem);

    &[data-state='selected'] td {
      background-color: color-mix(in srgb, var(--cascivo-color-accent) 8%, transparent);
    }
  }

  /* Empty cell */
  .emptyCell {
    padding: var(--cascivo-space-8) var(--cascivo-space-4);
    text-align: center;
    color: var(--cascivo-color-text-muted);
  }

  /* Expansion row */
  .expansionRow {
    &[data-state='closed'] {
      display: none;
    }
  }

  .expansionGrid {
    overflow: hidden;
  }

  .expansionInner {
    padding: var(--cascivo-space-4);
  }

  /* Expand button */
  .expandButton {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    inline-size: 1.5rem;
    block-size: 1.5rem;
    background: none;
    border: none;
    cursor: pointer;
    color: var(--cascivo-color-text-muted);
    border-radius: var(--cascivo-radius-control);
    outline: none;

    &:focus-visible {
      box-shadow: 0 0 0 2px var(--cascivo-color-accent);
    }

    &:hover {
      color: var(--cascivo-color-text);
      background-color: var(--cascivo-color-bg-subtle);
    }
  }

  .chevron {
    display: block;
    inline-size: 0.75rem;
    block-size: 0.75rem;
    border-inline-end: 2px solid currentColor;
    border-block-end: 2px solid currentColor;
    transform: rotate(45deg);
    transition: transform var(--cascivo-duration-150) var(--cascivo-ease-out);
  }

  .expandButton[data-state='open'] .chevron {
    transform: rotate(-135deg);
  }

  /* Loading shimmer — compositor-safe (translate only) */
  .shimmer {
    display: block;
    block-size: 0.875rem;
    inline-size: 80%;
    position: relative;
    overflow: hidden;
    background-color: var(--cascivo-color-bg-subtle);
    border-radius: var(--cascivo-radius-indicator);

    &::after {
      content: '';
      position: absolute;
      inset: 0;
      translate: -100% 0;
      background: linear-gradient(90deg, transparent, var(--cascivo-color-surface), transparent);
      animation: global(cascivo-shimmer) var(--cascivo-duration-500, 500ms)
        var(--cascivo-ease-in-out, ease-in-out) infinite;
    }
  }

  /* Footer pagination */
  .footer {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: var(--cascivo-space-4);
    padding: var(--cascivo-space-3) var(--cascivo-space-4);
    border-block-start: 1px solid var(--cascivo-color-border);
    font-size: var(--cascivo-text-sm);
  }

  .pageSize {
    display: flex;
    align-items: center;
    gap: var(--cascivo-space-2);
    color: var(--cascivo-color-text-muted);

    select {
      appearance: none;
      height: 2rem;
      padding-inline: var(--cascivo-space-2);
      font-family: var(--cascivo-font-sans);
      font-size: var(--cascivo-text-sm);
      color: var(--cascivo-color-text);
      background-color: var(--cascivo-color-surface);
      border: 1px solid var(--cascivo-color-border);
      border-radius: var(--cascivo-radius-field);
      cursor: pointer;
      outline: none;

      &:focus-visible {
        border-color: var(--cascivo-color-accent);
        box-shadow: 0 0 0 3px color-mix(in srgb, var(--cascivo-color-accent) 20%, transparent);
      }
    }
  }

  .range {
    color: var(--cascivo-color-text-muted);
    white-space: nowrap;
  }

  .pageButtons {
    display: flex;
    gap: var(--cascivo-space-1);
  }

  .pageButton {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    inline-size: 2rem;
    block-size: 2rem;
    background: none;
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-control);
    cursor: pointer;
    color: var(--cascivo-color-text);
    font-size: var(--cascivo-text-base);
    outline: none;
    transition:
      background-color var(--cascivo-duration-150) var(--cascivo-ease-out),
      border-color var(--cascivo-duration-150) var(--cascivo-ease-out);

    &:hover:not(:disabled) {
      background-color: var(--cascivo-color-bg-subtle);
      border-color: var(--cascivo-color-border-strong);
    }

    &:focus-visible {
      border-color: var(--cascivo-color-accent);
      box-shadow: 0 0 0 3px color-mix(in srgb, var(--cascivo-color-accent) 20%, transparent);
    }

    &:disabled {
      /* Dim via a muted foreground, not opacity — opacity:0.4 on the glyph
         dropped the disabled arrow below 4.5:1 (WCAG color-contrast). */
      color: var(--cascivo-color-text-muted);
      cursor: not-allowed;
    }
  }

  /* Grid keyboard mode: the focused cell, not a control inside it, carries the ring. Inset
     so it is not clipped by the neighbouring cells or the scroller. */
  .table[role='grid'] :is(th, td):focus-visible {
    outline: 2px solid var(--cascivo-color-accent);
    outline-offset: -2px;
  }

  /* An editable cell hosts an Editable whose preview button has its own padding; the cell
     gives that padding back so the row keeps its density height. */
  .table td[data-editable] {
    padding-inline: calc(
      var(--cascivo-data-table-cell-gap, var(--cascivo-space-4)) - var(--cascivo-space-1)
    );
  }

  /* Screen-reader only utility */
  .srOnly {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }
}
